// Hero code editor: language tabs + typing animation.
//
// Progressive enhancement: the full, highlighted code for every language is
// already in the HTML (generated by lib/code-samples.js). This script only
// switches panels and plays a typing effect in an aria-hidden overlay, so the
// real code stays readable by screen readers and nothing is announced per
// character. Every newly selected language is typed out from the start.

(() => {
    const editor = document.querySelector("[data-editor]");

    if (!editor) {
        return;
    }

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const tabs = [...editor.querySelectorAll('[role="tab"]')];
    const panels = [...editor.querySelectorAll('.editor-code[role="tabpanel"]')];
    const titleLabel = editor.querySelector("[data-editor-title]");
    const overlay = editor.querySelector(".editor-typing code");
    const overlayFrame = overlay.parentElement;

    const caret = document.createElement("span");
    caret.className = "code-caret";
    caret.setAttribute("aria-hidden", "true");

    // Typing speed: about 22 ms per character, at most 1.8 s per snippet
    const MS_PER_COST = 22;
    const MAX_DURATION = 1800;
    const LINE_PAUSE = 3;

    // First view: start typing once the entrance fade has reached this opacity
    const ENTRANCE_OPACITY = 0.9;

    let runId = 0;
    let frame = null;
    let isVisible = false;
    let startWhenVisible = null;

    const panelFor = (lang) => panels.find((panel) => panel.dataset.lang === lang);


    // Stop any running animation and clear the overlay
    function cancel() {
        runId += 1;

        if (frame) {
            cancelAnimationFrame(frame);
            frame = null;
        }

        startWhenVisible = null;
        overlay.replaceChildren();
        editor.classList.remove("is-typing");
    }


    // Show a panel's complete code with the caret at the end
    function showComplete(panel) {
        cancel();

        const lines = panel.querySelectorAll(".code-line");
        lines[lines.length - 1].append(caret);
    }


    // Copy the panel into the overlay with all text emptied, and return
    // the typing steps: one unit per character (indentation all at once).
    function prepare(panel) {
        overlay.replaceChildren(...panel.querySelector("code").cloneNode(true).childNodes);

        const units = [];

        overlay.querySelectorAll(".code-line").forEach((line) => {
            line.classList.add("is-pending");

            const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT);
            const nodes = [];

            while (walker.nextNode()) {
                nodes.push(walker.currentNode);
            }

            if (!nodes.length) {
                units.push({ line, node: null, text: "", chars: 0, cost: LINE_PAUSE });
                return;
            }

            nodes.forEach((node, index) => {
                const text = node.data;
                const isIndent = node.parentElement.classList.contains("tok-ws");

                node.data = "";

                if (isIndent) {
                    units.push({ line, node, text, chars: text.length, cost: index === 0 ? LINE_PAUSE : 0 });
                    return;
                }

                for (let i = 0; i < text.length; i += 1) {
                    // Spaces are quicker; a little jitter gives a human rhythm
                    const base = text[i] === " " ? 0.5 : 1;
                    const pause = index === 0 && i === 0 ? LINE_PAUSE : 0;

                    units.push({ line, node, text, chars: 1, cost: base * (0.6 + Math.random() * 0.8) + pause });
                }
            });
        });

        return units;
    }


    function type(panel, { afterEntrance = false } = {}) {
        cancel();

        if (reducedMotion.matches) {
            showComplete(panel);
            return;
        }

        const id = runId;
        const units = prepare(panel);
        const totalCost = units.reduce((sum, unit) => sum + unit.cost, 0);
        const duration = Math.min(MAX_DURATION, totalCost * MS_PER_COST);

        editor.classList.add("is-typing");
        overlay.querySelector(".code-line").append(caret);

        let index = 0;
        let spent = 0;
        let startTime = null;

        function tick(now) {
            if (id !== runId) {
                return;
            }

            startTime ??= now;

            const budget = ((now - startTime) / duration) * totalCost;
            let last = null;

            while (index < units.length && spent + units[index].cost <= budget) {
                const unit = units[index];

                unit.line.classList.remove("is-pending");

                if (unit.node) {
                    unit.node.data = unit.text.slice(0, unit.node.data.length + unit.chars);
                }

                spent += unit.cost;
                index += 1;
                last = unit;
            }

            if (last) {
                if (last.node) {
                    last.node.after(caret);
                } else {
                    last.line.append(caret);
                }

                // Long lines on narrow screens: keep the caret in view
                overlayFrame.scrollLeft = Math.max(0, caret.offsetLeft + 24 - overlayFrame.clientWidth);
            }

            if (index < units.length) {
                frame = requestAnimationFrame(tick);
            } else {
                showComplete(panel);
            }
        }

        // Waiting uses the same frame as typing, so cancel() stops either one
        function waitForEntrance() {
            if (id !== runId) {
                return;
            }

            frame = requestAnimationFrame(
                Number(getComputedStyle(editor).opacity) >= ENTRANCE_OPACITY ? tick : waitForEntrance
            );
        }

        const begin = () => {
            if (afterEntrance) {
                waitForEntrance();
            } else {
                frame = requestAnimationFrame(tick);
            }
        };

        if (isVisible) {
            begin();
        } else {
            startWhenVisible = begin;
        }
    }


    function select(lang, { focus = false } = {}) {
        const panel = panelFor(lang);

        // Re-selecting the current language does nothing (no restart)
        if (!panel || panel.classList.contains("is-active")) {
            if (focus) {
                tabs.find((tab) => tab.dataset.lang === lang)?.focus();
            }
            return;
        }

        tabs.forEach((tab) => {
            const isSelected = tab.dataset.lang === lang;

            tab.setAttribute("aria-selected", String(isSelected));
            tab.tabIndex = isSelected ? 0 : -1;

            if (isSelected && focus) {
                tab.focus();
            }
        });

        panels.forEach((p) => p.classList.toggle("is-active", p === panel));
        titleLabel.textContent = panel.dataset.title;

        // Choosing a tab means the editor is in use, even if it's barely on screen
        isVisible = true;

        type(panel);
    }


    // Tabs: click, and arrow / Home / End keys (WAI-ARIA tabs pattern)
    tabs.forEach((tab, index) => {
        tab.addEventListener("click", () => select(tab.dataset.lang));

        tab.addEventListener("keydown", (event) => {
            const keys = {
                ArrowRight: (index + 1) % tabs.length,
                ArrowLeft: (index - 1 + tabs.length) % tabs.length,
                Home: 0,
                End: tabs.length - 1,
            };

            if (event.key in keys) {
                event.preventDefault();
                select(tabs[keys[event.key]].dataset.lang, { focus: true });
            }
        });
    });


    // Start typing the default language once the editor is on screen
    if ("IntersectionObserver" in window) {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    isVisible = true;
                    observer.disconnect();
                    startWhenVisible?.();
                    startWhenVisible = null;
                }
            },
            { threshold: 0.3 }
        );

        observer.observe(editor);
    } else {
        isVisible = true;
    }

    type(panels.find((panel) => panel.classList.contains("is-active")) || panels[0], { afterEntrance: true });
})();
